\echo P2 the last pass in full: per-step elapsed seconds and errors
SELECT key, value FROM jsonb_each(coalesce((SELECT value->'step_elapsed_s' FROM ingestion_state WHERE key = 'paper_session_last_pass'), '{}'::jsonb)) ORDER BY (value::text)::float DESC NULLS LAST;
SELECT key, left(value::text, 300) AS error FROM jsonb_each(coalesce((SELECT value->'errors' FROM ingestion_state WHERE key = 'paper_session_last_pass'), '{}'::jsonb));
\echo P3 coverage watermark and newest snapshot
SELECT value, to_timestamp((value->>'at')::float) AS at FROM ingestion_state WHERE key = 'coverage_integrity_last';
SELECT max(computed_at) AS newest_snapshot FROM coverage_funnel_snapshots;
